import fs from 'node:fs';
import path from 'node:path';
import 'dotenv/config';
const dir=path.join(process.env.TEMP,'gigorave-parser-tests-57fa654e-1622-4b98-9ad2-015e38a701bf');
process.env.GIGORAVE_DATA_DIR=dir;process.env.GIGORAVE_DB_PATH=path.join(dir,'bot.sqlite');process.env.QTICKETS_DB_PATH=path.join(dir,'qtickets.sqlite');
const {buildSinglePublicEventMessage}=await import('../src/app/botApplication.js');
const {prepareEventAnnouncementCopies,selectEventAnnouncement,getOriginalEventAnnouncement}=await import('../src/features/events/eventAnnouncementCopies.js');
const rows=JSON.parse(fs.readFileSync('data/event-verified-snapshot.json','utf8')).items.map(x=>x.event);
const measured=rows.map(e=>({event:e,raw:buildSinglePublicEventMessage(e,'telegram','',true)})).sort((a,b)=>b.raw.length-a.raw.length);
console.log('LARGEST_HEADERS',JSON.stringify(measured.slice(0,3).map(x=>({title:x.event.title,chars:x.raw.length,blocks:x.raw.split('\n\n').map(b=>({label:b.slice(0,50),chars:b.length}))}))));
const event=measured[0].event;
console.log('MODEL_CHECK_START',JSON.stringify({title:event.title,header:measured[0].raw.length,originalChars:getOriginalEventAnnouncement(event).length}));
const [prepared]=await prepareEventAnnouncementCopies([event],{ensureSummaries:false});
if(prepared.announcementPreparationError) throw Error(prepared.announcementPreparationError);
const body=selectEventAnnouncement(prepared,'telegram');
const card=buildSinglePublicEventMessage(prepared,'telegram');
if(card.length>1000)throw Error('Full caption overflow');
const result={title:event.title,originalChars:getOriginalEventAnnouncement(event).length,announcementChars:body.length,captionChars:card.length,card};
fs.writeFileSync('logs/caption-model-smoke-20261113.json',JSON.stringify(result,null,2));
console.log('MODEL_CHECK_OK',JSON.stringify(result));
process.exit(0);
